    int t = 60000 / n;                           // 每个 X 的时长（毫秒）
    // 节奏型：X  X  X/2  X/2  X —— 中间两个音符时值减半
    cout << t << ' ' << t << ' ' << t / 2 << ' ' << t / 2 << ' ' << t << '\n';
    return 0;
}
```

