using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    int n = (int)s.size();

    string ans;
    // 第 i 声（i 从 1 开始）吼出的长度是 len = n - i + 1。
    // i 为奇数：白风从左往右吼 S 的前 len 个字符；
    // i 为偶数：墨龙从右往左吼 S 的后 len 个字符（即 S 尾部 len 个字符倒过来）。
    for (int i = 1; i <= n; i++) {
